insert into public.guest_form_templates (
  template_key, template_name, template_version, business_line, form_title, form_description, agreement_html, fields_schema, requires_signature, pdf_title
) values
(
  'minor_driver_authorization','Minor Driver Authorization & Liability Agreement','2026-08-20','Tours','Minor Driver Authorization & Liability Agreement','Parent or legal guardian authorization for a minor to operate a vehicle during a guided tour.',
  $$<p>In consideration of Epic 4X4 Adventures allowing the above-named minor to operate a vehicle during a guided tour, I, the undersigned parent or legal guardian, hereby agree to the following:</p><h3>1. Assumption of Responsibility</h3><p>I acknowledge that Epic 4X4 Adventures has no prior knowledge of the Minor’s driving experience, skill, maturity, or readiness to safely operate a UTV in off-road conditions. I accept full responsibility for evaluating and affirming the Minor’s readiness to participate as a driver.</p><h3>2. Guide Discretion</h3><p>I understand and agree that permission for the Minor to operate any Epic 4X4 Adventures vehicle is granted solely at the discretion of the tour guide. This permission may be limited or revoked at any time during the tour for safety or operational reasons. The Minor may not be allowed to drive through specific technical or hazardous sections of trail.</p><h3>3. Release of Liability</h3><p>I agree to indemnify, defend, and hold harmless Epic 4X4 Adventures, its owners, employees, agents, and affiliates from any and all claims, actions, damages, or liabilities arising out of or connected with the Minor’s participation as a driver, including but not limited to any injury, property damage, or third-party claims.</p><h3>4. Duty to Notify</h3><p>I agree to immediately notify the guide if, at any point, I believe the Minor is not physically, emotionally, or mentally fit to operate the vehicle.</p><p>By signing below, I confirm that I have read and understood this agreement, and I voluntarily accept its terms.</p>$$,
  '[{"key":"minor_first_name","label":"Minor First Name","type":"text","required":true},{"key":"minor_last_name","label":"Minor Last Name","type":"text","required":true},{"key":"minor_dob","label":"Date of Birth","type":"date","required":true},{"key":"minor_license_number","label":"Minor''s License Number","type":"text","required":true},{"key":"license_expiration_date","label":"Expiration Date","type":"date","required":true},{"key":"issuing_authority","label":"Issuing Authority","type":"text","required":true},{"key":"guardian_first_name","label":"Parent/Legal Guardian First Name","type":"text","required":true},{"key":"guardian_last_name","label":"Parent/Legal Guardian Last Name","type":"text","required":true}]'::jsonb,true,'Minor Driver Authorization & Liability Agreement'
),
(
  'pet_acknowledgment','Animal/Pet Acknowledgment and Assumption of Risk','2026-08-20','Rentals','Animal/Pet Acknowledgment and Assumption of Risk','Acknowledgment of risks and responsibilities for bringing an animal in an Epic 4X4 Adventures rental vehicle.',
  $$<p>While Epic 4X4 Adventures does not strictly prohibit animals in our rental vehicles, we strongly urge guests to reconsider bringing pets on the trail. Off-roading involves sudden movements, steep inclines, uneven terrain, and unpredictable conditions that can be dangerous to unrestrained animals.</p><p>By choosing to bring an animal (including ADA-recognized Service Animals) into an Epic 4X4 Adventures vehicle, you, the Renter, acknowledge and agree to the following:</p><p><strong>No Safety Equipment Provided:</strong> Epic 4X4 Adventures does not provide, install, or guarantee the effectiveness of any animal safety equipment, including but not limited to cages, crates, seatbelt harnesses, or restraints.</p><p><strong>Animal Stress &amp; Discomfort:</strong> Please be aware that animals that have never been in this environment often have an extremely unpleasant time. The loud operating noise of the vehicles, combined with the constant jostling, bouncing, and rough terrain, can cause severe stress, anxiety, motion sickness, and physical discomfort for your pet.</p><p><strong>Lap Riding &amp; 2-Seat Vehicles:</strong> If a passenger attempts to hold an animal in their lap—especially in a 2-seat vehicle—it creates a severe safety hazard. A passenger holding a pet cannot safely grip the vehicle's grab bars to brace themselves over rough terrain. Conversely, if the passenger uses the grab bars to secure their own safety, the animal cannot be held and is at an even greater risk of injury or being thrown from the vehicle.</p><p><strong>Assumption of Inherent Risks:</strong> You understand that off-road trails pose significant risks to animals. Animals can be thrown around the cabin, injured by trail hazards, or encounter dangerous local wildlife, specifically snakes. Because the entire vehicle is wide open, animals can easily escape or be exposed to these outside elements. You assume 100% of the risk associated with bringing an animal on the trail and in the vehicle.</p><p><strong>Service Animals:</strong> We welcome ADA-recognized Service Animals. However, the physical realities and risks of off-road driving apply equally to all animals. You acknowledge that Epic 4X4 Adventures cannot guarantee the physical safety of your Service Animal while operating the vehicle on off-road terrain.</p><p><strong>Release of Liability:</strong> You agree to fully release, waive, and hold harmless Epic 4X4 Adventures, its owners, and its employees from any and all claims, lawsuits, or liability whatsoever regarding your animal. This includes any injury, death, loss, or distress the animal may experience during the rental period, regardless of the cause.</p><p><strong>Vehicle Damage &amp; Cleaning:</strong> You assume full financial responsibility for any damage caused by the animal to the interior or exterior of the vehicle (including scratched upholstery, chewed components, or biological accidents). An additional $250 detailing fee will be applied if the vehicle requires excessive cleaning due to pet hair, dirt, or waste.</p><p>I have read and fully understand the risks associated with bringing an animal into an off-road vehicle. I voluntarily assume all responsibility for the safety and well-being of my animal.</p>$$,
  '[{"key":"renter_full_name","label":"Renter Full Name","type":"text","required":true},{"key":"animal_type","label":"Type of Animal","type":"text","required":true}]'::jsonb,true,'Animal/Pet Acknowledgment and Assumption of Risk'
)
on conflict (template_key) do update set template_name=excluded.template_name,template_version=excluded.template_version,business_line=excluded.business_line,form_title=excluded.form_title,form_description=excluded.form_description,agreement_html=excluded.agreement_html,fields_schema=excluded.fields_schema,requires_signature=excluded.requires_signature,pdf_title=excluded.pdf_title,is_active=true,updated_at=now();
